python3 -c "
import re, os

for dirpath, _, filenames in os.walk('src'):
    for fn in filenames:
        if not fn.endswith('.rs'):
            continue
        path = os.path.join(dirpath, fn)
        with open(path) as f:
            content = f.read()

        # Remove test modules
        # This is a rough heuristic: remove #[cfg(test)] mod tests { ... }
        lines = content.split('\n')
        in_test = False
        test_depth = 0
        prod_lines = []
        for i, line in enumerate(lines, 1):
            if '#[cfg(test)]' in line:
                in_test = True
                test_depth = 0
                continue
            if in_test:
                test_depth += line.count('{') - line.count('}')
                if test_depth <= 0 and '{' not in line and '}' in line:
                    in_test = False
                continue
            if '#[test]' in line:
                # Skip individual test functions too
                continue
            prod_lines.append((i, line))

        for lineno, line in prod_lines:
            if '.unwrap()' in line and not line.strip().startswith('//'):
                print(f'{path}:{lineno}: {line.strip()}')
"

